steps.script:
var acts = PhaseManager.get_current_phase_instance().get_available_actions()
var out := []
for a in acts:
	out.append(str(a.get("description", "")))
print("[wp-o5] redeploy actions: ", out)
return [out.has("Kaptin's Hat: Send Boyz to Strategic Reserves"), out.has("Redeploy Boyz"), out.has("Redeploy Flash Gitz"), out.any(func(s): return str(s).contains("Battlewagon"))]
